.gantt-container {
  width: 100%;
  overflow-x: auto;
  border: 1px solid #ccc;
}

.gantt-table {
  border-collapse: collapse;
  min-width: 1200px;
}

.gantt-user-header {
  position: sticky;
  left: 0;
  z-index: 2;
  min-width: 180px;
  height: 60px;
  background: #fff;
  border: 1px solid #ddd;
  border-bottom: 5px solid #ddd;
}

.gantt-slot-header {
  min-width: 24px;
  padding: 4px;
  border: 1px solid #eee;
  font-size: 12px;
  font-weight: normal;
  border-bottom: 5px solid #ddd;
}

.gantt-user-cell {
  position: sticky;
  left: 0;
  z-index: 1;
  padding: 4px;
  background: #fff;
  border: 1px solid #ddd;
  /* font-weight: bold; */
  font-size: 14px;
  white-space: nowrap;
}

.gantt-slot-cell {
  width: 24px;
  height: 25px;
  border: 1px solid #eee;
  text-align: center;
  font-size: 10px;
  color: #fff;
  cursor: pointer;
  transition: background 0.2s ease;
}

.gantt-slot-cell:hover {
  filter: brightness(0.9);
}

.week-even {
  background-color: #e0e0e0;
}

.week-odd {
  background-color: #dee2ff;
}

.week-even.slot-solid {
  background-color: rgba(231, 231, 231, 0.6);
}

.week-even.slot-faded {
  background-color: rgba(250, 250, 250, 0.3);
  border-right: 3px solid #ccc;
}

.week-odd.slot-solid {
  background-color: rgba(222, 226, 255, 0.8);
}

.week-odd.slot-faded {
  background-color: rgba(222, 226, 255, 0.3);
  border-right: 3px solid #ccc;
}

.day-divider {
  border-right: 2px solid #999 !important;
}

.today-column {
  position: relative;
  box-shadow: inset 0 0 0 2px #ff9800;
}

.gantt-container {
  overflow-x: auto;
  cursor: grab;
  user-select: none;
}

.gantt-container:active {
  cursor: grabbing;
}

.gantt-toolbar {
  margin-bottom: 10px;
}

.gantt-toolbar button {
  padding: 6px 12px;
  cursor: pointer;
}

