import React, { useMemo, useEffect, useRef } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

const getFirstFullWeekMonday = (year = new Date().getFullYear()) => {
  const d = new Date(year, 0, 1);
  // Move to first Monday
  while (d.getDay() !== 1) {
    d.setDate(d.getDate() + 1);
  }

  return d;
};

const slotToDate = (year = new Date().getFullYear(), slot = 17) => {
  const firstMonday = getFirstFullWeekMonday(year);
  const weekIndex = Math.floor(slot / 10);
  const remainder = slot % 10;
  const dayIndex = Math.floor(remainder / 2);
  const amPmIndex = remainder % 2;
  const result = new Date(firstMonday);

  result.setDate(firstMonday.getDate() + weekIndex * 7 + dayIndex);

  return {
    date: result,
    halfDay: amPmIndex === 0 ? "AM" : "PM",
  };
};

const isTodaySlot = (year, slot) => {
  const slotDate = slotToDate(year, slot).date;
  const today = new Date();

  return (
    slotDate.getFullYear() === today.getFullYear() &&
    slotDate.getMonth() === today.getMonth() &&
    slotDate.getDate() === today.getDate()
  );
};

export default function GanttTable() {
  const totalSlots = 520;
  const isDev = false;

  const isDragging = useRef(false);
  const startX = useRef(0);
  const scrollLeftStart = useRef(0);

  const containerRef = useRef(null);
  const todayColumnRef = useRef(null);

  const handleMouseDown = (e) => {
    isDragging.current = true;
    startX.current = e.pageX - containerRef.current.offsetLeft;
    scrollLeftStart.current = containerRef.current.scrollLeft;
  };

  const handleMouseLeave = () => {
    isDragging.current = false;
  };

  const handleMouseUp = () => {
    isDragging.current = false;
  };

  const handleMouseMove = (e) => {
    if (!isDragging.current) return;

    e.preventDefault();

    const x = e.pageX - containerRef.current.offsetLeft;
    const walk = x - startX.current;

    containerRef.current.scrollLeft = scrollLeftStart.current - walk;
  };

  useEffect(() => {
    if (containerRef.current && todayColumnRef.current) {
      const container = containerRef.current;
      const column = todayColumnRef.current;

      const scrollLeft =
        column.offsetLeft - container.clientWidth / 2 + column.clientWidth / 2;

      container.scrollLeft = scrollLeft;
    }
  }, []);

  const scrollToToday = () => {
    if (containerRef.current && todayColumnRef.current) {
      const container = containerRef.current;
      const column = todayColumnRef.current;

      const scrollLeft =
        column.offsetLeft - container.clientWidth / 2 + column.clientWidth / 2;

      container.scrollTo({
        left: scrollLeft,
        behavior: "smooth",
      });
    }
  };

  const ganttData = isDev ? ganttDataTest : appsmith.model.data;

  const slots = useMemo(() => {
    return Array.from({ length: totalSlots }, (_, i) => i);
  }, []);

  return (
    <>
      <div className="gantt-toolbar">
        <button onClick={scrollToToday}>Back to Today</button>
      </div>
      <div
        className="gantt-container"
        ref={containerRef}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseLeave}
      >
        <table className="gantt-table">
          <thead>
            <tr>
              <th className="gantt-user-header">Equipment</th>
              {slots.map((slot) => (
                <th
                  key={slot}
                  ref={
                    isTodaySlot(ganttData.year, slot) ? todayColumnRef : null
                  }
                  className={`gantt-slot-header ${Math.floor(slot / 10) % 2 === 0 ? "week-even" : "week-odd"}
                                    ${slot % 2 === 1 ? "day-divider" : ""} ${isTodaySlot(ganttData.year, slot) ? "today-column" : ""}`}
                >
                  {slotToDate(ganttData.year, slot).date.toLocaleDateString(
                    "en-GB",
                    {
                      weekday: "short",
                      day: "2-digit",
                      month: "2-digit",
                    },
                  )}{" "}
                  {slotToDate(ganttData.year, slot).halfDay}
                </th>
              ))}
            </tr>
          </thead>
          {/* MAIN TABLE BODY: Dynamically constructed */}
          <tbody>
            {ganttData.equipment.map((user) => {
              const bookingMap = {};
              user.bookings.forEach((b) => {
                bookingMap[b.slot] = b;
              });
              return (
                <tr key={user.Call_Id}>
                  <td className="gantt-user-cell">{user.eq_description}</td>
                  {slots.map((slot) => {
                    const booking = bookingMap[slot];
                    return (
                      <td
                        key={slot}
                        title={booking?.name || ""}
                        className={`
                            gantt-slot-cell
                            ${Math.floor(slot / 10) % 2 === 0 ? "week-even" : "week-odd"}
                            ${slot % 2 === 0 ? "slot-solid" : "slot-faded"}
                            ${isTodaySlot(ganttData.year, slot) ? "today-column" : ""}
                            `}
                        style={{ background: booking ? booking.color : null }}
                      >
                        {booking?.label || ""}
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </>
  );
}

appsmith.onReady(() => {
	ReactDOM.render(<GanttTable />, document.getElementById("root"));
});
appsmith.onModelChange(() => {
	ReactDOM.render(<GanttTable />, document.getElementById("root"));
});
